49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        validateRequiredFields(ownerFieldsDto);
106	        HttpHeaders headers = new HttpHeaders();
107	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
108	        this.clinicService.saveOwner(owner);
109	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
110	        headers.setLocation(UriComponentsBuilder.newInstance()
111	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
112	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
113	    }
114	
115	    /**
116	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
117	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
118	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
119	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
120	     *
121	     * @param ownerFieldsDto the submitted owner fields
122	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
123	     */
124	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
125	        List<String> invalidFields = new ArrayList<>();
126	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
127	            invalidFields.add("firstName");
128	        }
129	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
130	            invalidFields.add("lastName");
131	        }
132	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
133	            invalidFields.add("address");
134	        }
135	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
136	            invalidFields.add("city");
137	        }
138	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
139	            invalidFields.add("telephone");
140	        }
141	        if (!invalidFields.isEmpty()) {
142	            throw new InvalidOwnerFieldsException(invalidFields);
143	        }
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
149	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
150	        if (currentOwner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        currentOwner.setAddress(ownerFieldsDto.getAddress());
154	        currentOwner.setCity(ownerFieldsDto.getCity());
155	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
156	        currentOwner.setLastName(ownerFieldsDto.getLastName());
157	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
158	        this.clinicService.saveOwner(currentOwner);
159	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Transactional
164	    @Override
165	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
166	        Owner owner = this.clinicService.findOwnerById(ownerId);
167	        if (owner == null) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        this.clinicService.deleteOwner(owner);
171	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
177	        Owner owner = this.clinicService.findOwnerById(ownerId);
178	        if (owner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        HttpHeaders headers = new HttpHeaders();
182	        Pet pet = petMapper.toPet(petFieldsDto);
183	        owner.setId(ownerId);
184	        pet.setOwner(owner);
185	        pet.getType().setName(null);
186	        this.clinicService.savePet(pet);
187	        PetDto petDto = petMapper.toPetDto(pet);
188	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
189	            .buildAndExpand(pet.getId()).toUri());
190	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
196	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
197	        if (currentOwner != null) {
